@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class WardedArcanaAudit {
 static final BlockPos POS=InfusionAudit.POS.offset(-10,-2,12),DOOR=POS.above(),PLATE=DOOR.north();static int ticks;static volatile boolean prepared;static ItemStack boundIron,boundGold;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_ARCANA FAIL "+s);System.out.println("TC4_ARCANA PASS "+s);}
 static UseOnContext context(net.minecraft.world.entity.player.Player p,BlockPos pos){return new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(pos.getCenter(),Direction.UP,pos,false));}
 static void prepare(ServerPlayer p){p.getInventory().selected=0;InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;RunicAudit.clear(p);var l=p.serverLevel();l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);for(int x=-4;x<=8;x++)for(int z=-4;z<=5;z++)for(int y=-1;y<=4;y++)l.setBlock(POS.offset(x,y,z),y==0?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);p.connection.teleport(POS.getX()+7,POS.getY()+2,POS.getZ()+3,0,0);
  p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(WardedArcana.DOOR.get()));var result=p.getMainHandItem().getItem().useOn(context(p,POS));check(result.consumesAction()&&l.getBlockState(DOOR).is(WardedArcana.DOOR.get())&&l.getBlockState(DOOR.above()).is(WardedArcana.DOOR.get()),"actual door placement creates twohalves");var t=WardedArcana.owned(l,DOOR);check(t.owner.equals(p.getGameProfile().getName())&&WardedArcana.owned(l,DOOR.above()).owner.equals(t.owner),"both halves ownedbyplacer");
  var fake=net.neoforged.neoforge.common.util.FakePlayerFactory.get(l,new com.mojang.authlib.GameProfile(UUID.nameUUIDFromBytes("TC4ArcanaGuest".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"ArcanaGuest"));fake.setPos(p.position());var hit=new BlockHitResult(DOOR.getCenter(),Direction.NORTH,DOOR,false);WardedArcana.DOOR.get().useWithoutItem(l.getBlockState(DOOR),l,DOOR,fake,hit);check(!l.getBlockState(DOOR).getValue(DoorBlock.OPEN),"stranger dooraccess denied");WardedArcana.DOOR.get().useWithoutItem(l.getBlockState(DOOR),l,DOOR,p,hit);check(l.getBlockState(DOOR).getValue(DoorBlock.OPEN)&&l.getBlockState(DOOR.above()).getValue(DoorBlock.OPEN),"owner opens both halves");WardedArcana.ArcaneDoor.toggle(l,DOOR,false);l.setBlock(DOOR.east(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);check(!l.getBlockState(DOOR).getValue(DoorBlock.OPEN),"ordinary redstone cannot opendoor");l.removeBlock(DOOR.east(),false);
  for(boolean gold:new boolean[]{false,true}){var blank=new ItemStack(WardedArcana.key(gold),2);p.setItemInHand(InteractionHand.MAIN_HAND,blank);blank.getItem().onItemUseFirst(blank,context(p,DOOR.above()));var bound=p.getInventory().items.stream().filter(i->i.is(WardedArcana.key(gold))&&NoteData.tag(i).contains("location")).findFirst().orElseThrow();check(blank.getCount()==1&&NoteData.tag(bound).getString("location").equals(DOOR.getX()+","+DOOR.getY()+","+DOOR.getZ())&&bound.hasFoil(),"actual boundkeylowerhalf location/glint/consume "+gold);if(gold)boundGold=bound.copy();else boundIron=bound.copy();}
  fake.setItemInHand(InteractionHand.MAIN_HAND,boundIron.copy());fake.getMainHandItem().getItem().onItemUseFirst(fake.getMainHandItem(),context(fake,DOOR));check(t.access.contains("0ArcanaGuest")&&WardedArcana.owned(l,DOOR.above()).access.contains("0ArcanaGuest")&&fake.getMainHandItem().isEmpty(),"iron keygrants permanent namedaccess bothhalves thenconsumed");WardedArcana.DOOR.get().useWithoutItem(l.getBlockState(DOOR),l,DOOR,fake,hit);check(l.getBlockState(DOOR).getValue(DoorBlock.OPEN),"guest opensdoor without carryingkey");WardedArcana.ArcaneDoor.toggle(l,DOOR,false);fake.setItemInHand(InteractionHand.MAIN_HAND,boundGold.copy());fake.getMainHandItem().getItem().onItemUseFirst(fake.getMainHandItem(),context(fake,DOOR));check(t.access.contains("1ArcanaGuest")&&fake.getMainHandItem().isEmpty(),"gold keyupgradesguest todelegation");fake.getInventory().clearContent();var blank=new ItemStack(WardedArcana.key(false),2);fake.setItemInHand(InteractionHand.MAIN_HAND,blank);blank.getItem().onItemUseFirst(blank,context(fake,DOOR));check(blank.getCount()==1&&fake.getInventory().items.stream().anyMatch(i->NoteData.tag(i).contains("location")),"gold guest canmintiron accesskeys");blank=new ItemStack(WardedArcana.key(true),2);fake.setItemInHand(InteractionHand.MAIN_HAND,blank);blank.getItem().onItemUseFirst(blank,context(fake,DOOR));check(blank.getCount()==2,"gold guest cannot mintgold masterkeys");
  l.setBlock(PLATE,WardedArcana.PLATE.get().defaultBlockState(),3);WardedArcana.assign(l,PLATE,p);var pt=WardedArcana.owned(l,PLATE);p.connection.teleport(PLATE.getX()+.5,PLATE.getY()+.05,PLATE.getZ()+.5,0,0);pt.setting=0;WardedArcana.ArcanePlate.evaluate(l,PLATE);check(l.getBlockState(PLATE).getValue(WardedArcana.ArcanePlate.POWERED)&&l.getBlockState(DOOR).getValue(DoorBlock.OPEN),"actual ownersteps compatibleplate opensdoor");for(var f:Direction.values())check(l.getBlockState(PLATE).getSignal(l,PLATE,f)==15&&l.getBlockState(PLATE).getDirectSignal(l,PLATE,f)==(f==Direction.UP?15:0),"plate weak15 strongUPonly "+f);
  pt.setting=1;WardedArcana.ArcanePlate.evaluate(l,PLATE);check(!l.getBlockState(PLATE).getValue(WardedArcana.ArcanePlate.POWERED)&&!l.getBlockState(DOOR).getValue(DoorBlock.OPEN),"mode1 excludes owner closesdoor");pt.setting=2;WardedArcana.ArcanePlate.evaluate(l,PLATE);check(l.getBlockState(PLATE).getValue(WardedArcana.ArcanePlate.POWERED),"mode2 includes authorizedowner");p.connection.teleport(POS.getX()+7,POS.getY()+2,POS.getZ()+3,0,0);var item=new ItemEntity(l,PLATE.getX()+.5,PLATE.getY()+.05,PLATE.getZ()+.5,new ItemStack(Items.DIRT));l.addFreshEntity(item);pt.setting=2;WardedArcana.ArcanePlate.evaluate(l,PLATE);check(!l.getBlockState(PLATE).getValue(WardedArcana.ArcanePlate.POWERED),"mode2 excludes droppeditems");pt.setting=1;WardedArcana.ArcanePlate.evaluate(l,PLATE);check(l.getBlockState(PLATE).getValue(WardedArcana.ArcanePlate.POWERED),"mode1 stillincludes droppeditems originalquirk");item.discard();pt.setting=0;WardedArcana.ArcanePlate.evaluate(l,PLATE);check(!l.getBlockState(PLATE).getValue(WardedArcana.ArcanePlate.POWERED),"releasedplate clears power");
  var wand=p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow().copy();p.setItemInHand(InteractionHand.MAIN_HAND,wand);fake.setItemInHand(InteractionHand.MAIN_HAND,wand.copy());check(!WardedArcana.removeWithWand(fake.getMainHandItem(),context(fake,DOOR)),"even golddelegate cannot dismantle owneddoor");var glass=DOOR.east(3);l.setBlock(glass,WardedArcana.GLASS.get().defaultBlockState(),3);WardedArcana.assign(l,glass,p);check(!fake.gameMode.destroyBlock(glass)&&l.getBlockState(glass).is(WardedArcana.GLASS.get()),"actual gameMode creativewardbreak canceled");var explosion=new Explosion(l,null,glass.getX()+.5,glass.getY()+.5,glass.getZ()+.5,4,false,Explosion.BlockInteraction.DESTROY);l.getBlockState(glass).onBlockExploded(l,glass,explosion);check(l.getBlockState(glass).is(WardedArcana.GLASS.get()),"wardedglass explosion immune");check(wand.getItem().onItemUseFirst(wand,context(p,glass)).consumesAction()&&l.isEmptyBlock(glass),"actual wand interaction reclaimsown wardedglass");
  var saved=t.saveWithFullMetadata(l.registryAccess());var copy=new WardedArcana.Owned(DOOR,l.getBlockState(DOOR));copy.loadWithComponents(saved,l.registryAccess());check(copy.owner.equals(t.owner)&&copy.access.equals(t.access),"owner and bothpermanentaccess levels persist");
  for(String key:List.of("ArcaneDoor","WardedGlass","IronKey","GoldKey","ArcanePressurePlate"))craft(p,key);
  for(int x=3;x<=5;x++)for(int y=1;y<=2;y++){var at=POS.offset(x,y,0);l.setBlock(at,WardedArcana.GLASS.get().defaultBlockState(),3);WardedArcana.assign(l,at,p);}pt.setting=0;pt.changed();p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.connection.teleport(POS.getX()+4,POS.getY()+3,POS.getZ()-6,20,15);prepared=true;
 }
 static void craft(ServerPlayer p,String key){var r=ArcaneRecipes.entries().stream().filter(e->e.key().equals(key)).findFirst().orElseThrow();var grid=new ArrayList<ItemStack>(Collections.nCopies(9,ItemStack.EMPTY));for(int i=0;i<r.ingredients().size();i++)if(!r.ingredients().get(i).isEmpty())grid.set(i,r.ingredients().get(i).getItems()[0].copy());check(r.matches(grid,Set.of("WARDEDARCANA"))&&!r.matches(grid,Set.of()),"researchgate "+key);var wand=WandParts.make(WandParts.CAPS.get("gold"),WandParts.RODDEFS.get("greatwood"));for(var a:thaumcraft.api.aspects.Aspect.getPrimalAspects())WandData.add(wand,a,50,true);var expected=wand.copy();WandData.consumeCrafting(expected,r.cost(),true,p);var table=new SimpleContainer(10);for(int i=0;i<9;i++)table.setItem(i,grid.get(i));table.setItem(9,wand);var menu=new ArcaneWorkbenchMenu(20,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.NULL,table);check(ItemStack.isSameItemSameComponents(menu.getSlot(0).getItem(),r.output())&&menu.getSlot(0).getItem().getCount()==r.output().getCount(),"actualworkbench output "+key);var output=menu.getSlot(0).remove(r.output().getCount());menu.getSlot(0).onTake(p,output);for(int i=0;i<9;i++)check(table.getItem(i).isEmpty(),"ingredientconsumed "+key+"/"+i);for(var a:thaumcraft.api.aspects.Aspect.getPrimalAspects())check(WandData.get(wand,a)==WandData.get(expected,a),"exactvis "+key+"/"+a.getTag());menu.removed(p);}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.arcanaAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==160){check(prepared&&WardedArcanaClient.rendered>0,"servermechanics and actualconnectedglassrenderer");LiquidDeathAudit.shot(mc,"warded-arcana-world.png");}if(ticks>=180&&(ticks-180)%20==0){check(prepared,"allmechanics complete");int i=(ticks-180)/20;if(i>=5){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("WARDEDARCANA"),i*2);mc.setScreen(book);}if(ticks>=185&&(ticks-185)%20==0)LiquidDeathAudit.shot(mc,"warded-arcana-book-"+(ticks-185)/20+".png");}
}
